rule YARA_CobaltStrike_Generic {
  meta:
    description = "Detect generic Cobalt Strike beacon binaries"
    author = "SOC"
    false_positive_score = 70
  strings:
    $a = { 4D 5A ?? ?? 50 45 00 00 }
    // ... existing patterns ...
  condition:
    $a and not (pe.authenticode.thumbprint in ("3A7B..C9F2") and pe.imports("kernel32.dll", "CreateThread"))
}

